import { getProducts } from "@/services/product";

export default async function Home() {
    const products = await getProducts();

    return (
        <main>
            <h1>Shopera Products</h1>

            {products.map((product: any) => (
                <div key={product.id}>
                    <h2>{product.title}</h2>
                    <p>{product.price}</p>
                </div>
            ))}
        </main>
    );
}